package com.lianxibu.site.service.sources;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.domain.identity.NodeTokens;import com.lianxibu.site.repository.jobs.JdbcSharedWriteEntry;import com.lianxibu.site.service.jobs.SharedWriteExecutor;import com.lianxibu.site.service.identity.NodeIdentityService;import java.nio.file.*;import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class SourceContractJavaGoNativeMySqlTest extends SourceContractTelemetryHttpMySqlTest {
 @TempDir Path directory;AtomicReference<Instant> at;
 @Test void actualGoSqliteJournalSenderJavaHttpNativeReceiptAndReplayFences()throws Exception{
  at=new AtomicReference<>(f.f.now);f.clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return at.get();}};var identity=new NodeIdentityService(f.nodes,new NodeTokens(new byte[32]),f.clock);f.service=new SourceContractSnapshotService(f.f.store,f.sources,identity,new SharedWriteExecutor(new JdbcSharedWriteEntry(f.f.db),new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.f.db)),f.clock);
  go("prepare");var original=f.f.tx.execute(s->f.f.store.latest(f.nodeId,f.sourceId));assertNotNull(original);assertEquals(3,original.input().snapshot().totalFailures());assertEquals(3,original.input().snapshot().events().size());assertEquals(f.f.now,original.receivedAt());assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));
  f.f.jdbc.update("UPDATE sources SET config_revision=config_revision+1,activation_stage='disabled' WHERE id=?",f.sourceId);at.set(f.f.now.plusSeconds(600));go("replay");assertEquals(original,f.f.tx.execute(s->f.f.store.latest(f.nodeId,f.sourceId)));assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));assertEquals(1,f.nodes.revoke(f.nodeId,1));go("revoked");assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));
 }
 void go(String mode)throws Exception{
  String executable=System.getenv("V02_GO_EXEC");assertNotNull(executable,"actual Go executable required for this explicit interop scope");var command=new ProcessBuilder(executable,"test","-json","./internal/outbox","-run","^TestSourceContractJavaHTTP$","-count=1");command.directory(Path.of("../collector").toAbsolutePath().normalize().toFile());var env=command.environment();env.put("GOTOOLCHAIN","auto");env.put("GOPROXY","off");env.remove("GOROOT");env.put("VSC_BASE_URL",root.substring(0,root.indexOf("/api/collector/" )).replace("http://","https://"));env.put("VSC_TOKEN",f.token);env.put("VSC_NODE",f.nodeId);env.put("VSC_SOURCE",f.sourceId);env.put("VSC_MODE",mode);env.put("VSC_NOW",new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter().format(at.get()));env.put("VSC_ORIGINAL",new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter().format(f.f.now));env.put("VSC_QUEUE",directory.resolve("queue.db").toString());env.put("VSC_FROZEN",directory.resolve("original.json").toString());Path log=Path.of("target/ri702-go-"+f.nodeId+"-"+mode+".jsonl").toAbsolutePath();command.redirectErrorStream(true).redirectOutput(log.toFile());var child=command.start();if(!child.waitFor(60,TimeUnit.SECONDS)){child.destroyForcibly();child.waitFor(10,TimeUnit.SECONDS);fail("actual fictional Go interop timeout");}Files.writeString(Path.of(log+".exit"),Integer.toString(child.exitValue()));assertEquals(0,child.exitValue(),()->{try{return Files.readString(log);}catch(Exception unavailable){return "actual Go child failed";}});String text=Files.readString(log);assertTrue(text.contains("\"Action\":\"pass\"")&&text.contains("TestSourceContractJavaHTTP"));assertFalse(text.contains("\"Action\":\"skip\"")||text.contains("\"Action\":\"fail\""));
 }
}
